export const aliases={idss:['idss','off-state','off state','drain leakage','drain-source leakage','zero gate voltage'],igss:['igss','gate leakage','gate-body leakage'],threshold:['threshold','vth','vgs(th)'],breakdown:['breakdown','avalanche'],settling:['settling','settle','stabilize','transient','delay'],guard:['guard','guarding','triax','fixture leakage'],shield:['shield','shielding','electrostatic','movement'],offset:['offset','baseline','background'],filter:['filter','averaging','throughput'],drift:['drift','warmup','warm up','temperature stability'],generated:['triboelectric','input bias','generated current'],verify:['verification','noise floor','verify'],rating:['absolute maximum','maximum rating'],hv:['interlock','enclosure','high voltage safety']};
export function tokens(s){return (s.toLowerCase().replace(/µ/g,'u').match(/[a-z0-9]+/g)||[]).filter(x=>!['the','a','an','is','to','of','for','and','in','at','what','how','do','i','it','my','can','with','this','on','why'].includes(x));}
export function retrieve(query,corpus,mode='hybrid',k=3){
 const q=tokens(query); const N=corpus.chunks.length; const texts=corpus.chunks.map(c=>tokens(c.title+' '+c.text+(mode==='hybrid'?' '+c.tags:'')));const avg=texts.reduce((a,t)=>a+t.length,0)/N;
 const matches=Object.entries(aliases).filter(([id,terms])=>terms.some(t=>query.toLowerCase().includes(t))).map(([id])=>id);
 return corpus.chunks.map((c,i)=>{let score=0;for(const w of q){const f=texts[i].filter(t=>t===w).length;if(!f)continue;if(mode==='keyword'){score++;continue;}const df=texts.filter(t=>t.includes(w)).length;score+=Math.log(1+(N-df+.5)/(df+.5))*f*2.2/(f+1.2*(.25+.75*texts[i].length/avg));}if(mode==='hybrid'&&matches.includes(c.id))score+=8;return {...c,score};}).filter(c=>c.score>0).sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id)).slice(0,k);
}
export function classify(s){const x=s.toLowerCase();let families=['idss','igss','threshold','breakdown'].filter(id=>aliases[id].some(t=>x.includes(t)));if(families.length>1)return {family:'ambiguous',reason:'Multiple test families appear. Choose a single measurement before planning.'};if(families.length===1)return {family:families[0],reason:families[0]==='idss'?'Drain leakage candidate; confirm conditions below.':'Evidence is available, but procedure generation is outside the IDSS scope.'};if(/leak|off.?current/.test(x))return {family:'ambiguous',reason:'Leakage alone does not identify the measured terminal. Clarify drain leakage (IDSS) versus gate leakage (IGSS).'};return {family:'unknown',reason:'No supported test family identified. Retrieve evidence or clarify the measurement.'};}
export function validate(p){const errors=[];for(const f of ['device','vds','vgs','temperature','limit','compliance','settling','samples'])if(p[f]===''||p[f]==null)errors.push({field:f,message:'Required value is missing.'});if(errors.length)return errors;
 if(p.device!=='2N7000')errors.push({field:'device',message:'Only the Vishay 2N7000 is supported for procedure generation.'});for(const f of ['vds','vgs','temperature','limit','compliance','settling','samples'])if(!Number.isFinite(Number(p[f])))errors.push({field:f,message:'Enter a finite number.'});
 if(!(Number(p.vds)>0&&Number(p.vds)<=48))errors.push({field:'vds',message:'Demo bias range is greater than 0 through 48 V.'});if(Number(p.vgs)!==0)errors.push({field:'vgs',message:'This IDSS workflow requires VGS = 0 V.'});if(Number(p.temperature)!==25)errors.push({field:'temperature',message:'Only the documented 25°C condition is supported.'});if(!(Number(p.limit)>0))errors.push({field:'limit',message:'Limit must be positive (µA).'});if(!(Number(p.compliance)>Number(p.limit)&&Number(p.compliance)<=1000))errors.push({field:'compliance',message:'Compliance must exceed the limit and be at most 1000 µA in this simulator.'});if(!(Number(p.settling)>0&&Number(p.settling)<=60))errors.push({field:'settling',message:'Choose a delay above 0 through 60 s.'});if(!Number.isInteger(Number(p.samples))||p.samples<3||p.samples>100)errors.push({field:'samples',message:'Use an integer from 3 through 100.'});if(!p.connections)errors.push({field:'connections',message:'Confirm the logical drain / source / gate connections.'});return errors;}
export function simulate(p,scenario='nominal',seed=42){const errors=validate(p);if(errors.length)throw new Error(errors.map(e=>e.field+': '+e.message).join('\n'));if(!['nominal','leaky','fixture','compliance'].includes(scenario))throw new Error('Unknown scenario');let state=Number(seed)>>>0;const rand=()=>{state=(1664525*state+1013904223)>>>0;return state/4294967296;};const trace=['OUTPUT OFF','RESET','CONNECT drain=HI source=LO gate=source','SET compliance '+p.compliance+' uA','SET VGS 0 V','SET VDS '+p.vds+' V','OUTPUT ON','WAIT '+p.settling+' s'];const rows=[];try{for(let i=0;i<p.samples;i++){const base=scenario==='leaky'?1.6:scenario==='compliance'?Number(p.compliance)*2:.22;const fixture=scenario==='fixture'?.9:0;const settling=.8*Math.exp(-(Number(p.settling)+i*.1)/.4);const raw=base*(Number(p.vds)/48)+fixture+settling+(rand()-.5)*.06;const clamped=raw>=Number(p.compliance);rows.push({sample:i+1,time_s:Number(p.settling)+i*.1,current_uA:Math.min(raw,Number(p.compliance)),compliance:clamped});if(clamped){trace.push('COMPLIANCE reached; abort acquisition');break;}}}finally{trace.push('SET VDS 0 V','OUTPUT OFF');}const compliance=rows.some(r=>r.compliance);const mean=rows.reduce((a,r)=>a+r.current_uA,0)/rows.length;return {scenario,seed,rows,mean_uA:mean,status:compliance?'INVALID: compliance':rows.some(r=>r.current_uA>p.limit)?'FAIL':'PASS',trace,comparison:'Every sampled absolute current must be at or below the user-approved limit.',datasheet_match:Number(p.vds)===48&&Number(p.limit)===1,model:'Synthetic illustrative currents; not a calibrated device or instrument model.'};}
export function procedure(p){const e=validate(p);if(e.length)throw new Error('Resolve validation errors first');return `# TestBridge: simulation only; no hardware driver\nfrom testbridge import run_simulation\n\nplan = ${JSON.stringify(p,null,2).replace(/true/g,'True').replace(/false/g,'False')}\nresult = run_simulation(plan, scenario="nominal", seed=42)\nprint(result)\n`;}
